<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import AppIcon from '../AppIcon.vue'
import PurchaseRequest from './PurchaseRequest.vue'
import { createProcurementDocument, getProcurementDocuments, transitionProcurementDocument } from '../../services/procurementService'
import { getMyRequests } from '../../services/staffRequestService'

const tabs = [
  { id: 'requests', label: 'Purchase Requests', icon: 'cart' },
  { id: 'orders', label: 'Purchase Orders', icon: 'file-text' },
  { id: 'receipts', label: 'Goods Received Notes', icon: 'inbox' },
]
const activeTab = ref('requests')
const documents = ref([])
const requests = ref([])
const loading = ref(true)
const saving = ref(false)
const error = ref('')
const notice = ref('')
const showForm = ref(false)
const form = reactive({ type: 'purchase_order', document_number: '', document_date: new Date().toISOString().slice(0, 10), supplier: '', purchase_order_id: '', notes: '', description: '', quantity: 1, unit_cost: '' })
const visibleDocuments = computed(() => documents.value.filter((doc) => activeTab.value === 'orders' ? doc.type === 'purchase_order' : doc.type === 'goods_received_note'))
const issuedOrders = computed(() => documents.value.filter((doc) => doc.type === 'purchase_order' && doc.status === 'issued'))
const purchaseRequests = computed(() => requests.value.filter((item) => item.type === 'purchase'))
const statusLabel = (status) => ({ pending: 'Awaiting approval', approved: 'Approved', rejected: 'Declined', draft: 'Draft', issued: 'Issued', received: 'Received' }[status] || status)
const money = (value) => `$${(Number(value) || 0).toFixed(2)}`
const load = async () => {
  loading.value = true
  error.value = ''
  try {
    const [docs, reqs] = await Promise.all([getProcurementDocuments(), getMyRequests()])
    documents.value = docs.data.data
    requests.value = reqs.data.data
  } catch (e) { error.value = e.response?.data?.message || 'Could not load procurement records.' }
  finally { loading.value = false }
}
onMounted(load)
const openForm = (type) => {
  Object.assign(form, { type, document_number: `${type === 'purchase_order' ? 'PO' : 'GRN'}-${Date.now().toString().slice(-8)}`, document_date: new Date().toISOString().slice(0, 10), supplier: '', purchase_order_id: '', notes: '', description: '', quantity: 1, unit_cost: '' })
  showForm.value = true
}
const save = async () => {
  saving.value = true; error.value = ''; notice.value = ''
  try {
    const isOrder = form.type === 'purchase_order'
    await createProcurementDocument({
      type: form.type, document_number: form.document_number, document_date: form.document_date || null,
      payload: { supplier: isOrder ? form.supplier : '', purchase_order_id: isOrder ? null : Number(form.purchase_order_id), notes: form.notes, items: [{ description: form.description, quantity: Number(form.quantity), unit_cost: isOrder && form.unit_cost !== '' ? Number(form.unit_cost) : null, received_quantity: isOrder ? null : Number(form.quantity) }] },
    })
    showForm.value = false; notice.value = 'Document saved as a draft.'; await load()
  } catch (e) { error.value = Object.values(e.response?.data?.errors || {}).flat()[0] || e.response?.data?.message || 'Could not save this document.' }
  finally { saving.value = false }
}
const advance = async (doc) => {
  error.value = ''; notice.value = ''
  try { await transitionProcurementDocument(doc.id, doc.type === 'purchase_order' ? 'issued' : 'received'); notice.value = 'Document status updated.'; await load() }
  catch (e) { error.value = e.response?.data?.message || 'Could not update document status.' }
}
</script>

<template>
  <main class="procurement">
    <header class="procurement__header"><div><p class="procurement__eyebrow"><span></span> PROCUREMENT WORKSPACE</p><h1>Procurement Management</h1><p class="procurement__intro">Request what you need, place orders, and record deliveries in one place.</p></div><div class="procurement__flow"><span>Request</span><i></i><span>Order</span><i></i><span>Receive</span></div></header>
    <nav class="procurement__tabs" aria-label="Procurement sections"><button v-for="tab in tabs" :key="tab.id" type="button" :class="{ 'is-active': activeTab === tab.id }" @click="activeTab = tab.id; showForm = false"><AppIcon :name="tab.icon" :size="18" />{{ tab.label }}</button></nav>
    <p v-if="error" class="procurement__alert" role="alert">{{ error }}</p><p v-if="notice" class="procurement__notice" role="status">{{ notice }}</p>
    <section v-if="activeTab === 'requests'" class="procurement__panel"><header class="procurement__panel-head"><div><h2>Purchase Requests</h2><p>Submit a request for supervisor approval and track its progress.</p></div><span class="procurement__count">{{ purchaseRequests.length }} requests</span></header><PurchaseRequest @submitted="load" /><div class="procurement__request-list"><h3>Recent requests</h3><p v-if="loading" class="procurement__empty">Loading requests…</p><p v-else-if="!purchaseRequests.length" class="procurement__empty">Your submitted purchase requests will appear here.</p><article v-for="item in purchaseRequests" :key="item.id" class="procurement__request-row"><span class="procurement__doc-icon"><AppIcon name="cart" :size="18" /></span><div><strong>{{ item.summary || item.details?.purpose || 'Purchase request' }}</strong><small>{{ new Date(item.submitted_at).toLocaleDateString() }} · {{ item.approver || 'Supervisor review' }}</small></div><span class="procurement__status" :class="`is-${item.status}`">{{ statusLabel(item.status) }}</span></article></div></section>
    <section v-else class="procurement__panel"><header class="procurement__panel-head"><div><h2>{{ activeTab === 'orders' ? 'Purchase Orders' : 'Goods Received Notes' }}</h2><p>{{ activeTab === 'orders' ? 'Create and issue supplier orders.' : 'Record items received against an issued purchase order.' }}</p></div><button type="button" class="procurement__primary" @click="openForm(activeTab === 'orders' ? 'purchase_order' : 'goods_received_note')"><AppIcon name="plus" :size="17" />New {{ activeTab === 'orders' ? 'Purchase Order' : 'Received Note' }}</button></header>
      <form v-if="showForm" class="procurement__form" @submit.prevent="save"><div class="procurement__form-title"><div><h3>{{ form.type === 'purchase_order' ? 'New Purchase Order' : 'New Goods Received Note' }}</h3><p>Saved documents start as drafts.</p></div><button type="button" class="procurement__close" aria-label="Close form" @click="showForm = false">×</button></div><div class="procurement__fields"><label>Document number<input v-model.trim="form.document_number" required maxlength="80" /></label><label>Date<input v-model="form.document_date" type="date" /></label><label v-if="form.type === 'purchase_order'">Supplier<input v-model.trim="form.supplier" maxlength="255" placeholder="Supplier name" /></label><label v-else>Issued purchase order<select v-model="form.purchase_order_id" required><option value="" disabled>Select an issued order</option><option v-for="order in issuedOrders" :key="order.id" :value="String(order.id)">{{ order.document_number }} · {{ order.payload?.supplier || 'Supplier' }}</option></select></label><label class="procurement__wide">Item description<input v-model.trim="form.description" required maxlength="500" placeholder="Describe the item" /></label><label>Quantity<input v-model.number="form.quantity" type="number" min="0.01" step="any" required /></label><label v-if="form.type === 'purchase_order'">Unit cost (USD)<input v-model.number="form.unit_cost" type="number" min="0" step="0.01" /></label><label class="procurement__wide">Notes<textarea v-model.trim="form.notes" rows="2" maxlength="5000"></textarea></label></div><footer><button type="button" class="procurement__secondary" @click="showForm = false">Cancel</button><button class="procurement__primary" type="submit" :disabled="saving">{{ saving ? 'Saving…' : 'Save draft' }}</button></footer></form>
      <div v-if="loading" class="procurement__empty">Loading procurement records…</div><div v-else-if="!visibleDocuments.length" class="procurement__empty procurement__empty--card"><span class="procurement__empty-icon"><AppIcon :name="activeTab === 'orders' ? 'file-text' : 'inbox'" :size="22" /></span><strong>No {{ activeTab === 'orders' ? 'purchase orders' : 'goods received notes' }} yet</strong><p>Create a document to start tracking procurement here.</p><button class="procurement__secondary" type="button" @click="openForm(activeTab === 'orders' ? 'purchase_order' : 'goods_received_note')">Create first document</button></div><div v-else class="procurement__documents"><article v-for="doc in visibleDocuments" :key="doc.id" class="procurement__document"><span class="procurement__doc-icon"><AppIcon :name="doc.type === 'purchase_order' ? 'file-text' : 'inbox'" :size="19" /></span><div class="procurement__document-main"><div class="procurement__document-title"><strong>{{ doc.document_number }}</strong><span class="procurement__status" :class="`is-${doc.status}`">{{ statusLabel(doc.status) }}</span></div><p>{{ doc.type === 'purchase_order' ? (doc.payload?.supplier || 'Supplier not specified') : `Purchase order #${doc.payload?.purchase_order_id || '—'}` }} · {{ doc.document_date || 'No date' }}</p><small>{{ doc.payload?.items?.map((item) => `${item.description} × ${item.quantity}`).join(' · ') }}</small></div><div v-if="doc.type === 'purchase_order' && doc.payload?.items?.[0]?.unit_cost" class="procurement__amount">{{ money(doc.payload.items[0].unit_cost * doc.payload.items[0].quantity) }}</div><button v-if="doc.status === 'draft'" class="procurement__secondary" type="button" @click="advance(doc)">{{ doc.type === 'purchase_order' ? 'Issue order' : 'Confirm receipt' }}</button></article></div>
    </section>
  </main>
</template>

<style scoped>
.procurement{--ink:#102e52;--muted:#657b98;--line:#dce6f2;--green:#087d67;color:var(--ink);padding:8px 0 38px}.procurement__header{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin:0 0 22px}.procurement__eyebrow{display:flex;align-items:center;gap:9px;color:var(--green);font-size:12px;font-weight:800;letter-spacing:.13em;margin:0 0 8px}.procurement__eyebrow span{width:8px;height:8px;border-radius:50%;background:#21ae91}.procurement h1{font-size:clamp(28px,2.6vw,36px);letter-spacing:-.035em;margin:0}.procurement__intro,.procurement__panel-head p{color:var(--muted);margin:6px 0 0;font-size:14px}.procurement__flow{display:flex;align-items:center;gap:9px;padding:11px 15px;border:1px solid var(--line);border-radius:12px;background:#fff;color:#55718f;font-size:12px;font-weight:700}.procurement__flow i{width:20px;height:1px;background:#b8c9dc}.procurement__tabs{display:inline-flex;align-items:center;gap:3px;width:max-content;max-width:100%;min-height:50px;box-sizing:border-box;padding:5px;border:1px solid var(--line);border-radius:12px;background:#f1f5f9;margin:0 0 16px;overflow-x:auto}.procurement__tabs button{box-sizing:border-box;flex:none;min-height:38px;margin:0!important;border:0;background:transparent;color:#526b88;padding:0 14px;border-radius:8px;font-family:inherit;font-size:13px;font-weight:600;line-height:1;display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;white-space:nowrap}.procurement__tabs button.is-active{color:#102e52;background:#fff;box-shadow:0 1px 5px #193b5718}.procurement__panel{border:1px solid var(--line);border-radius:15px;background:#fff;padding:20px;box-shadow:0 5px 16px #193b5707}.procurement__panel-head{display:flex;justify-content:space-between;align-items:center;gap:16px;padding-bottom:15px;border-bottom:1px solid #eaf0f7;margin-bottom:16px}.procurement__panel-head h2{font-size:20px;margin:0}.procurement__count{background:#eff8f5;color:#08745f;border-radius:30px;padding:7px 11px;font-size:12px;font-weight:700}.procurement__primary,.procurement__secondary{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid #cbd9e9;border-radius:9px;padding:9px 13px;background:#fff;color:#183d62;font-family:inherit;font-size:13px;font-weight:700;cursor:pointer}.procurement__primary{background:#087d67;color:#fff;border-color:#087d67}.procurement__primary:disabled{opacity:.6;cursor:wait}.procurement__alert,.procurement__notice{border-radius:10px;padding:12px 15px;margin:0 0 14px}.procurement__alert{background:#fff1f0;color:#a42a2a}.procurement__notice{background:#eaf8f2;color:#08745f}.procurement__request-list{margin-top:22px}.procurement__request-list h3{font-size:15px;margin:0 0 10px}.procurement__request-row,.procurement__document{display:flex;align-items:center;gap:13px;padding:13px 4px;border-top:1px solid #edf1f6}.procurement__doc-icon,.procurement__empty-icon{display:grid;place-items:center;flex:none;width:38px;height:38px;border-radius:10px;background:#edf3ff;color:#275bb5}.procurement__request-row>div,.procurement__document-main{flex:1;min-width:0}.procurement__request-row strong,.procurement__document-title strong{font-size:13px}.procurement__request-row small,.procurement__document p,.procurement__document small{display:block;color:var(--muted);font-size:12px;margin:5px 0 0}.procurement__status{white-space:nowrap;padding:5px 9px;border-radius:30px;background:#eff3f8;color:#506681;font-size:11px;font-weight:700}.procurement__status.is-approved,.procurement__status.is-issued,.procurement__status.is-received{background:#e8f7f1;color:#08745f}.procurement__status.is-pending{background:#fff5df;color:#94620b}.procurement__status.is-rejected{background:#fff0ef;color:#ad3b35}.procurement__form{background:#f8fafd;border:1px solid var(--line);border-radius:12px;padding:16px;margin:0 0 18px}.procurement__form-title,.procurement__form footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.procurement__form h3{font-size:16px;margin:0}.procurement__form-title p{font-size:12px;color:var(--muted);margin:4px 0 0}.procurement__close{border:0;background:transparent;color:#7487a0;font-size:26px;cursor:pointer}.procurement__fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px;margin:16px 0}.procurement__fields label{display:grid;gap:7px;color:#284765;font-weight:700;font-size:12px}.procurement__fields input,.procurement__fields select,.procurement__fields textarea{box-sizing:border-box;width:100%;border:1px solid #dce5ef;border-radius:8px;background:#fff;padding:10px 11px;color:var(--ink);font-family:inherit;font-size:14px;font-weight:400;outline-color:#138b75}.procurement__wide{grid-column:1/-1}.procurement__form footer{justify-content:flex-end}.procurement__empty{color:var(--muted);padding:18px 0;font-size:14px}.procurement__empty--card{display:flex;align-items:center;flex-direction:column;text-align:center;padding:32px 16px;border:1px dashed var(--line);border-radius:12px}.procurement__empty--card strong{margin-top:12px}.procurement__empty--card p{color:var(--muted);font-size:13px;margin:5px 0 15px}.procurement__document-title{display:flex;align-items:center;gap:10px}.procurement__amount{font-weight:800;font-size:14px;color:#254463}
/* The existing request form is reused here, but its standalone page chrome is removed. */
.procurement :deep(.lv){width:100%;max-width:none;margin:0;padding:0;font-size:14px}.procurement :deep(.lv-head){display:none}.procurement :deep(.lv-card){border:0;border-radius:0;background:transparent;box-shadow:none}.procurement :deep(.lv-form){width:100%;max-width:none;gap:15px;padding:3px 0}.procurement :deep(.lv-form textarea){min-height:70px}.procurement :deep(.rq-table-wrap){max-width:100%;overflow-x:auto;border:1px solid #e4ebf3;border-radius:9px}.procurement :deep(.rq-table){min-width:620px}.procurement :deep(.rq-total){margin-top:0}.procurement :deep(.lv-form__foot){padding-top:12px;border-top:1px solid #edf1f6}
@media(max-width:760px){.procurement__header{align-items:flex-start;flex-direction:column}.procurement__tabs{overflow:auto}.procurement__panel{padding:16px}.procurement__fields{grid-template-columns:repeat(2,minmax(0,1fr))}.procurement__document{align-items:flex-start;flex-wrap:wrap}.procurement__document-main{min-width:calc(100% - 60px)}}@media(max-width:480px){.procurement__fields{grid-template-columns:1fr}.procurement__panel-head{align-items:flex-start;flex-direction:column}.procurement__request-row{align-items:flex-start;flex-wrap:wrap}.procurement__flow{width:max-content}}
</style>
